<?php use App\Core\Csrf; ?>
<div class="page-heading"><div><div class="breadcrumb-lite">Human Resource Management / Officers / Add</div><h1>Add Officer</h1></div></div>
<form method="post" enctype="multipart/form-data" action="<?= e(url('hr/officers')) ?>"><?= Csrf::field() ?>
<div class="form-section"><h5>Identity</h5><div class="row g-3"><div class="col-md-3"><label class="form-label">NIC *</label><input class="form-control" name="nic" required></div><div class="col-md-3"><label class="form-label">Employee Number</label><input class="form-control" name="employee_number"></div><div class="col-md-3"><label class="form-label">Title *</label><select class="form-select" name="title_id" required><option value="">Select</option><?php foreach($titles as $r): ?><option value="<?= e($r['id']) ?>"><?= e($r['name_en']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Gender *</label><select class="form-select" name="gender" required><option value="">Select</option><option>MALE</option><option>FEMALE</option></select></div>
<div class="col-md-4"><label class="form-label">Name with Initials *</label><input class="form-control" name="name_with_initials" required></div><div class="col-md-8"><label class="form-label">Full Name (English) *</label><input class="form-control" name="full_name_en" required></div><div class="col-md-6"><label class="form-label">Full Name (Sinhala)</label><input class="form-control" name="full_name_si"></div><div class="col-md-6"><label class="form-label">Full Name (Tamil)</label><input class="form-control" name="full_name_ta"></div>
<div class="col-md-3"><label class="form-label">Date of Birth *</label><input type="date" class="form-control" name="date_of_birth" required></div><div class="col-md-3"><label class="form-label">Civil Status</label><select class="form-select" name="civil_status_id"><option value="">Optional</option><?php foreach($civilStatuses as $r): ?><option value="<?= e($r['id']) ?>"><?= e($r['name_en']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Photograph <span class="text-muted small">JPG/PNG, max 5 MB (Optional)</span></label><input type="file" class="form-control" name="photograph" accept="image/jpeg,image/png"></div></div></div>
<div class="form-section"><h5>Contact</h5><div class="row g-3"><div class="col-md-6"><label class="form-label">Permanent Address *</label><textarea class="form-control" name="permanent_address" required></textarea></div><div class="col-md-6"><label class="form-label">Temporary Address</label><textarea class="form-control" name="temporary_address"></textarea></div><div class="col-md-3"><label class="form-label">Telephone Number</label><input class="form-control" name="primary_mobile" placeholder="0XXXXXXXXX or +94XXXXXXXXX"></div><div class="col-md-3"><label class="form-label">WhatsApp Number</label><input class="form-control" name="alternative_mobile" placeholder="0XXXXXXXXX or +94XXXXXXXXX"><div class="form-text">At least one contact number is required.</div></div><div class="col-md-3"><label class="form-label">Personal Email</label><input type="email" class="form-control" name="personal_email"></div><div class="col-md-3"><label class="form-label">Official Email</label><input type="email" class="form-control" name="official_email"></div></div></div>
<div class="form-section"><h5>Employment</h5><div class="row g-3"><div class="col-md-3"><label class="form-label">Initial Appointment Date *</label><input type="date" class="form-control" name="initial_appointment_date" required></div><div class="col-md-3"><label class="form-label">Appointment Nature *</label><select class="form-select" name="appointment_nature_id" required><option value="">Select</option><?php foreach($appointmentNatures as $r): ?><option value="<?= e($r['id']) ?>"><?= e($r['name_en']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Primary Designation *</label><select class="form-select" name="primary_designation_id" required><option value="">Select</option><?php foreach($designations as $r): ?><option value="<?= e($r['id']) ?>"><?= e($r['name_en']) ?> (<?= e($r['designation_level']) ?>)</option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Class</label><select class="form-select" name="class_id"><option value="">Not Applicable</option><?php foreach($classes as $r): ?><option value="<?= e($r['id']) ?>"><?= e($r['name_en']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Service Permanency *</label><select id="service-permanency" class="form-select" name="arpa_service_permanency" required><option value="">Select...</option><option value="PERMANENT_IN_SERVICE">Permanent In Service</option><option value="NOT_PERMANENT_IN_SERVICE">Not Permanent In Service</option></select></div><div class="col-md-4"><label class="form-label">Permanented Date <span id="permanented-date-required" hidden>*</span></label><input id="service-permanented-date" type="date" class="form-control" name="service_permanented_date"></div><div class="col-md-4"><label class="form-label">Officer Status *</label><select class="form-select" name="officer_status_id" required><option value="">Select</option><?php foreach($statuses as $r): ?><option value="<?= e($r['id']) ?>"><?= e($r['name_en']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Start Date *</label><input id="officer-effective-from" type="date" class="form-control" name="effective_from" value="<?= date('Y-m-d') ?>" required></div></div></div>
<div class="form-section"><h5>Office Assignment</h5><div class="row g-3"><div class="col-md-8"><label class="form-label">Assigned Office</label><select class="form-select" name="initial_office_id"><option value="">No initial Office selected</option><?php foreach($availableOffices as $office): ?><option value="<?= e($office['id']) ?>"><?= e($office['dad_number'].' - '.$office['name_en'].' ('.$office['office_type'].')') ?></option><?php endforeach; ?></select><div class="form-text">Only Offices available to your current Working Context are shown.</div></div><div class="col-md-4"><label class="form-label">Effective From</label><input id="office-effective-from" type="date" class="form-control" name="office_effective_from" value="<?= date('Y-m-d') ?>"></div><div class="col-12"><div class="alert alert-info mb-0">If selected, this Office assignment remains pending and becomes operational only when the Officer is approved.</div></div></div></div>
<button class="btn btn-primary">Submit</button> <a class="btn btn-outline-secondary" href="<?= e(url('hr/officers')) ?>">Cancel</a></form>
<script>document.addEventListener('DOMContentLoaded',()=>{const officerDate=document.getElementById('officer-effective-from');const officeDate=document.getElementById('office-effective-from');let manuallyChanged=false;officeDate?.addEventListener('change',()=>{manuallyChanged=true;});officerDate?.addEventListener('change',()=>{if(officeDate&&!manuallyChanged)officeDate.value=officerDate.value;});const permanency=document.getElementById('service-permanency');const permanentedDate=document.getElementById('service-permanented-date');const marker=document.getElementById('permanented-date-required');const syncPermanency=()=>{const required=permanency?.value==='PERMANENT_IN_SERVICE';if(permanentedDate){permanentedDate.required=required;if(!required)permanentedDate.value='';}if(marker)marker.hidden=!required;};permanency?.addEventListener('change',syncPermanency);syncPermanency();});</script>
